/*
 * A351122  Irregular triangle read by rows in which row n lists the number of
 *          divisions by 2 after tripling steps in the Collatz 3x+1 trajectory
 *          of 2n+1 until it reaches 1.
 * https://oeis.org/A351122
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy, tabf
 * Formula:   not stated
 * Range:     u8 n <= 55, u16 n <= 92, u32 n <= 92, u64 n <= 92, u128 n <= 92,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Implements A351122: a(n) is generated by iterating the Collatz
   map on odd numbers, recording the exponent of 2 in each (3x+1)
   step; the sequence is the concatenation of these runs for the
   starting odd numbers 3,5,7,… */

seq_t a(idx_t n)
{
    idx_t cum = 0;
    for (idx_t row = 1; ; ++row) {
        seq_t odd = (seq_t)((seq_t)row * 2 + 1);   /* 2·row+1 */

        while (odd != 1) {
            seq_t y = odd * 3 + 1;                /* 3·odd+1 */
            idx_t t = 0;
            seq_t tmp = y;
            while ((tmp & 1) == 0) {              /* trailing zeros */
                ++t;
                tmp /= 2;
            }
            ++cum;
            if (cum == n) {
                return (seq_t)t;
            }
            odd = tmp;                            /* next odd */
        }
    }
}
